$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ClosureResults";$case='mixed_endpoint_pair_v2';$exe="$root\Build\Release\m78-closure-$case.exe";$dest="$out\mixed-endpoint-pair-v2"
function Upload($p,$n){for($attempt=0;$attempt -lt 10;$attempt++){try{Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null;return}catch{if($attempt -eq 9){throw};Start-Sleep -Milliseconds 200}}}
try{
if((Test-Path $exe) -or (Test-Path $dest)){throw 'Preserve prior paired capture'};Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-mixed_endpoint_v2-build.json" -OutFile "$out\mixed-endpoint-link-receipt.json";$build=[IO.File]::ReadAllText("$out\mixed-endpoint-link-receipt.json")|ConvertFrom-Json;Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-mixed_endpoint_v2-m78-closure-mixed_endpoint_v2.exe.bin" -OutFile $exe;if((Get-Item $exe).Length -ne $build.executableBytes -or (Get-FileHash $exe).Hash.ToLower() -ne $build.executableSHA256){throw 'Exact already-linked final witness identity changed'}
$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$out\temp";$env:TMP=$env:TEMP;$env:APPDATA="$out\userdata\Roaming";$env:LOCALAPPDATA="$out\userdata\Local";$runs=@()
foreach($mode in @('cold-write','cold-read')){$name="m78-closure-mixed-endpoint-pair-v2-$mode";if($mode -eq 'cold-write'){$env:JUDAS_DIAGNOSTIC_CONTINUE_WRITE='1'}else{$env:JUDAS_DIAGNOSTIC_CONTINUE_WRITE=$null};$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process $exe -WorkingDirectory "$root\Source" -ArgumentList @($dest,$mode) -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;throw 'Only owned witness timeout'};$p.Refresh();$exit=$p.ExitCode;$p.Dispose();$watch.Stop();$files=@();foreach($f in @(Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'})+@(Get-ChildItem "$dest\slots" -File)){$report="$name-$($f.Name)";Upload $f.FullName $report;$files+=@{path=$f.FullName;reportName=$report;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}};$run=@{run=$name;exitCode=$exit;expectedExitCode=0;seconds=$watch.Elapsed.TotalSeconds;executableSHA256=$build.executableSHA256;arguments=@($dest,$mode);observerOnlyContinueWrite=($mode -eq 'cold-write');files=$files};$runs+=$run;$rp="$out\$name.json";$run|ConvertTo-Json -Depth 5|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";if($exit -ne 0){throw 'Actual endpoint pair failed'}}
$rp="$out\m78-closure-$case-build.json";@{scope='Exact already-linked final witness reused by SHA; NEW paired save and uninterrupted observation versus fresh-process restoration. Diagnostic continuation only records original simulation after capture, no altered solver/controllers/thresholds.';case=$case;archive=$build.archive;replacementObjects=$build.replacementObjects;reusedExecutableSHA256=$build.executableSHA256;executable=$exe;executableBytes=$build.executableBytes;runs=$runs;generatedFiles=@(@{path=$exe;name=[IO.Path]::GetFileName($exe);bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe).Hash.ToLower()});ownedLargeEvidence=@();freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload $exe ('m78-closure-'+$case+'-'+[IO.Path]::GetFileName($exe)+'.bin')
}catch{$_|Out-String|Set-Content "$out\m78-closure-$case-error.txt";Upload "$out\m78-closure-$case-error.txt" "m78-closure-$case-error.txt";exit 1}
